#include <algorithm>
#include <cstdio>
#include <iostream>
using namespace std;

using ll = long long;

int main() {
    int n, m;
    scanf("%d%d", &n, &m);

    const int L = n + 1;
    ll ans = 0;

    for (int a = m + 1; a <= n - m; ++a) {
        int lef = m + 1;
        int rig = min(2 * a - 1, n - m);

        while (lef <= rig) {
            int mid = (lef + rig) >> 1;
            ll t = L - (1LL * (L - a) * (2 * a - mid) - 1) / (mid + a);

            if (t <= m + 1)
                lef = mid + 1;
            else
                rig = mid - 1;
        }

        ans += 1LL * (n - 2 * m) * (lef - m - 1);

        for (int b = lef; b <= 2 * a - 1 && b <= n - m; ++b) {
            ll t = L - (1LL * (L - a) * (2 * a - b) - 1) / (b + a);

            if (t <= n - m)
                ans += n - m - t + 1;
            else
                break;
        }
    }

    cout << ans * 3 << '\n';
    return 0;
}

